package com.finflow.payment; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="outbox_events") class OutboxEvent{@Id UUID id;UUID aggregateId;String eventType;@Column(columnDefinition="text")String payload;String status;int attempts;Instant createdAt;Instant publishedAt;protected OutboxEvent(){}static OutboxEvent of(UUID a,String t,String p){var e=new OutboxEvent();e.id=UUID.randomUUID();e.aggregateId=a;e.eventType=t;e.payload=p;e.status="PENDING";e.createdAt=Instant.now();return e;}}